head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setImageSrc]<br/>inputType='textImage' 인 Body Column 의 imageSrc 속성을 설정합니다.",
    "validation" : [
        "Column 의 viewType='icon' 인 경우에 imageSrc 속성에 설정한 이미지가 Body Column 에 표시되어야 합니다.",
        "columnInfo(필수) 파라미터로 imageSrc 속성을 설정하려는 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정되어야 합니다.",
        "src(필수) 파라미터로 Body Column 에 적용할 이미지의 경로를 문자열로 설정할 수 있어야 합니다.",
        "src(필수) 파라미터에 상대경로, 절대경로, 프로토콜 포함 경로를 설정할 수 있어야 합니다.",
        "src(필수) 파라미터에 PNG, JPG, JPEG, GIF, SVG 등 웹브라우저가 지원하는 모든 이미지 파일을 설정할 수 있어야 합니다.",
        "setImageSrc() 메소드는 Body Column 전체의 imageSrc 속성을 설정하므로 해당 Column 의 모든 Cell 에 동일한 이미지가 적용되어야 합니다.",
        "setCellImageSrc() 메소드로 특정 Body Cell 의 imageSrc 속성이 설정된 경우 Column 보다 Body Cell 의 imageSrc 속성이 우선 적용되어야 합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 파라미터 기본 선택값 설정 (정적 select1 은 초기 selectedIndex 미적용)
    par_columnInfo.setSelectedIndex(2);
    par_src.setSelectedIndex(0);

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - Column 구성(정의 인덱스) : 0 name(text) / 1 hid(textImage, 숨김) / 2 timg(textImage) / 3 cimg(textImage, Row 1 Cell imageSrc 설정)
//    · 인덱스 1 을 setColumnVisible(1, false) 로 숨김 → 숨겨진 Column 도 인덱스에 포함되므로
//      화면상 두번째로 보이는 timg 의 Column 인덱스는 2 가 됨
//    · 3 cimg : Row 1 만 setCellImageSrc 로 Cell imageSrc 를 설정 → @spec2(Cell 우선) 확인용
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column 구성(인덱스) : 0 = name(text) / 1 = hid(textImage, viewType=icon, setColumnVisible 로 숨김) / 2 = timg(textImage, viewType=icon) / 3 = cimg(textImage, viewType=icon, Row 1 만 setCellImageSrc 로 Cell imageSrc = ico_fav_on.svg 설정)\n[절차] columnInfo 와 src 를 선택하고 setImageSrc 버튼을 클릭하세요.\n[확인] 결과창의 Column 전체 Cell 표시 텍스트 / 이미지 경로와 그리드 화면의 아이콘 표시를 비교하세요."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) ===
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="hid" name="hid" dataType="text"></w2:column>';
    strDlt += '<w2:column id="timg" name="timg" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cimg" name="cimg" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "John", "hid": "H0", "timg": "수정", "cimg": "삭제" },
        { "name": "Jane", "hid": "H1", "timg": "수정", "cimg": "삭제" },
        { "name": "Mike", "hid": "H2", "timg": "수정", "cimg": "삭제" },
        { "name": "Amy",  "hid": "H3", "timg": "수정", "cimg": "삭제" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 그리드 직접 구성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:660px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setImageSrc test grid"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol1" value="name (0, text)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="hid (1, 숨김)"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol3" value="timg (2, textImage)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="cimg (3, Row 1 Cell 설정)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="textImage" viewType="icon" id="hid" dataList="hid"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="textImage" viewType="icon" id="timg" dataList="timg"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="textImage" viewType="icon" id="cimg" dataList="cimg"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 인덱스 1 (hid) 숨김 → 숨겨진 Column 도 인덱스에 포함됨을 검증
    target1.setColumnVisible(1, false);

    // @spec2 : Column 인덱스 3 의 Row 1 Body Cell 에만 Cell imageSrc 설정 (Cell 우선 적용 확인용)
    target1.setCellImageSrc(1, 3, "/cm/images/base/ico_fav_on.svg");
}



// Body Cell 의 표시 텍스트 / 이미지 경로 확인
scwin.getCellImgInfo = function (rowIndex, colIndex) {
    let cellEl = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + colIndex + "']");
    if (!cellEl) {
        return "(Cell 없음)";
    }
    let imgEl = cellEl.querySelector("img");
    let src = (imgEl && imgEl.getAttribute("src")) ? imgEl.getAttribute("src") : "(이미지 미표시)";
    return cellEl.textContent + " / " + src;
}



scwin.btn_setImageSrc_onclick = function () {
    let columnInfo = Number(par_columnInfo.getText());
    let srcText = par_src.getText();

    let src;
    if (srcText === "(프로토콜 포함 경로)") {
        src = location.origin + "/cm/images/base/ico_grid_del.svg";
    } else {
        src = srcText;
    }

    target1.setImageSrc(columnInfo, src);

    // Column 전체 Cell 의 표시 텍스트 / 이미지 경로 수집
    let detail = [];
    for (let i = 0; i < 4; i++) {
        detail.push("[Row " + i + "] " + scwin.getCellImgInfo(i, columnInfo));
    }

    wf_body_bottom.getObj("scwin").setReturnValue("setImageSrc(" + columnInfo + ", '" + src + "') 호출 후 Column 전체 Cell (표시 텍스트 / 이미지 경로) : " + detail.join(", "));
}
